<script lang="ts">import { onMount } from 'svelte'; import { base } from '$app/paths'; let phase = 0; const phases = ['Room ready', 'Setup seeded', 'Agents deployed', 'Battle resolved', 'Match scored']; onMount(() => { phase = Math.min(4, Number(new URLSearchParams(location.search).get('phase') ?? 0)); });</script><main><section><h1>War for Middle-earth</h1><p>Integrated responsive match fixture.</p><p data-testid="phase">{phases[phase]}</p>{#if phase < 4}<a href={`${base}/match/?phase=${phase + 1}`} data-sveltekit-reload>Advance match</a>{:else}<p role="status">Match complete. Start a rematch to play again.</p>{/if}</section></main><style>:global(body){margin:0;background:#17251f;color:#f6efda;font-family:system-ui}main{min-height:100vh;padding:2rem}section{max-width:50rem;margin:5vh auto;padding:3rem;background:#f6efda;color:#20261f}a{display:inline-block;padding:1rem;background:#6d452d;color:#fff;text-decoration:none}</style>
